const express=require('express'),{Pool}=require('pg'),bcrypt=require('bcryptjs'),jwt=require('jsonwebtoken'),multer=require('multer'),path=require('path'),fs=require('fs'),xlsx=require('xlsx');
const app=express(); app.use(express.json({limit:'2mb'}));
const PORT=process.env.PORT||3000, SECRET=process.env.JWT_SECRET||'CHANGE_THIS_SECRET', UP=path.join(__dirname,'uploads'); fs.mkdirSync(UP,{recursive:true});
const db=new Pool({connectionString:process.env.DATABASE_URL});
const upload=multer({dest:UP,limits:{fileSize:10*1024*1024}});
const q=async(sql,p=[])=>db.query(sql,p); const num=x=>Number(x||0);
const sign=u=>jwt.sign({id:u.id,name:u.name,email:u.email,role:u.role},SECRET,{expiresIn:'7d'});
function auth(req,res,next){try{const h=req.headers.authorization||'';req.user=jwt.verify(h.startsWith('Bearer ')?h.slice(7):'',SECRET);next()}catch(e){res.status(401).json({error:'Login required'})}}
function admin(req,res,next){if(req.user.role!=='admin')return res.status(403).json({error:'Admin only'});next()}
app.get('/durga.jpg',(req,res)=>res.type('jpg').send(Buffer.from('','base64')));
app.get('/api/health',async(req,res)=>{try{await q('SELECT 1');res.json({ok:true})}catch(e){res.status(500).json({ok:false})}});
app.post('/api/setup-admin',async(req,res)=>{try{if(num((await q('SELECT count(*) n FROM users')).rows[0].n)>0)return res.status(409).json({error:'Setup already completed'});const{name,email,password}=req.body;if(!name||!email||!password||password.length<6)return res.status(400).json({error:'Name, email and 6+ character password required'});const h=await bcrypt.hash(password,12),r=await q("INSERT INTO users(name,email,password_hash,role) VALUES($1,$2,$3,'admin') RETURNING id,name,email,role",[name,email.toLowerCase(),h]);res.json({user:r.rows[0],token:sign(r.rows[0])})}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/login',async(req,res)=>{try{const r=await q('SELECT * FROM users WHERE lower(email)=lower($1) AND active=true',[req.body.email||'']);const u=r.rows[0];if(!u||!(await bcrypt.compare(req.body.password||'',u.password_hash)))return res.status(401).json({error:'Invalid email or password'});res.json({user:{id:u.id,name:u.name,email:u.email,role:u.role},token:sign(u)})}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/me',auth,(req,res)=>res.json(req.user));
app.get('/api/dashboard',auth,async(req,res)=>{try{const[d,e,b,t]=await Promise.all([q('SELECT COALESCE(SUM(amount),0) n FROM donations'),q('SELECT COALESCE(SUM(amount),0) n FROM expenses'),q('SELECT COALESCE(SUM(allocated_amount),0) n FROM budgets'),q("SELECT transaction_date,transaction_type,amount,description,payment_mode FROM transaction_log ORDER BY transaction_date DESC,created_at DESC LIMIT 10")]);res.json({donation:num(d.rows[0].n),expense:num(e.rows[0].n),budget:num(b.rows[0].n),fund:num(d.rows[0].n)-num(e.rows[0].n),transactions:t.rows})}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/donations',auth,async(req,res)=>{const s=(req.query.search||'').trim(),from=req.query.from||'1900-01-01',to=req.query.to||'2999-12-31';const r=await q("SELECT * FROM donations WHERE donated_at BETWEEN $1 AND $2 AND (donor_name ILIKE $3 OR COALESCE(mobile,'') ILIKE $3 OR COALESCE(payment_mode,'') ILIKE $3) ORDER BY donated_at DESC,id DESC",[from,to,'%'+s+'%']);res.json(r.rows)});
app.get('/api/expenses',auth,async(req,res)=>{const s=(req.query.search||'').trim(),from=req.query.from||'1900-01-01',to=req.query.to||'2999-12-31';const r=await q("SELECT * FROM expenses WHERE spent_at BETWEEN $1 AND $2 AND (expense_head ILIKE $3 OR COALESCE(description,'') ILIKE $3 OR COALESCE(bill_reference,'') ILIKE $3) ORDER BY spent_at DESC,id DESC",[from,to,'%'+s+'%']);res.json(r.rows)});
app.get('/api/budgets',auth,async(req,res)=>res.json((await q('SELECT * FROM budgets ORDER BY created_at DESC')).rows));
app.post('/api/donations',auth,admin,async(req,res)=>{const x=req.body;if(!x.donor_name||!x.amount||!x.donated_at)return res.status(400).json({error:'Donor, amount and date are required'});const c=await db.connect();try{await c.query('BEGIN');const r=await c.query('INSERT INTO donations(donor_name,mobile,amount,payment_mode,donation_for,remarks,donated_at) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING *',[x.donor_name,x.mobile||'',x.amount,x.payment_mode||'',x.donation_for||'',x.remarks||'',x.donated_at]);await c.query("INSERT INTO transaction_log(transaction_date,transaction_type,amount,description,payment_mode,remarks,source_id) VALUES($1,'Donation',$2,$3,$4,$5,$6)",[x.donated_at,x.amount,'Donation received',x.payment_mode||'',x.remarks||'',r.rows[0].id]);await c.query('COMMIT');res.json(r.rows[0])}catch(e){await c.query('ROLLBACK');res.status(500).json({error:e.message})}finally{c.release()}});
app.put('/api/donations/:id',auth,admin,async(req,res)=>{const x=req.body;const c=await db.connect();try{await c.query('BEGIN');const r=await c.query('UPDATE donations SET donor_name=$1,mobile=$2,amount=$3,payment_mode=$4,donation_for=$5,remarks=$6,donated_at=$7 WHERE id=$8 RETURNING *',[x.donor_name,x.mobile||'',x.amount,x.payment_mode||'',x.donation_for||'',x.remarks||'',x.donated_at,req.params.id]);if(!r.rows[0])throw Error('Donation not found');await c.query("UPDATE transaction_log SET transaction_date=$1,amount=$2,payment_mode=$3,remarks=$4 WHERE transaction_type='Donation' AND source_id=$5",[x.donated_at,x.amount,x.payment_mode||'',x.remarks||'',req.params.id]);await c.query('COMMIT');res.json(r.rows[0])}catch(e){await c.query('ROLLBACK');res.status(500).json({error:e.message})}finally{c.release()}});
app.delete('/api/donations/:id',auth,admin,async(req,res)=>{const c=await db.connect();try{await c.query('BEGIN');await c.query("DELETE FROM transaction_log WHERE transaction_type='Donation' AND source_id=$1",[req.params.id]);await c.query('DELETE FROM donations WHERE id=$1',[req.params.id]);await c.query('COMMIT');res.json({ok:true})}catch(e){await c.query('ROLLBACK');res.status(500).json({error:e.message})}finally{c.release()}});
app.post('/api/expenses',auth,admin,async(req,res)=>{const x=req.body;if(!x.expense_head||!x.amount||!x.spent_at)return res.status(400).json({error:'Expense head, amount and date are required'});const c=await db.connect();try{await c.query('BEGIN');const r=await c.query('INSERT INTO expenses(expense_head,description,amount,payment_mode,paid_by,bill_reference,remarks,spent_at) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *',[x.expense_head,x.description||'',x.amount,x.payment_mode||'',x.paid_by||'',x.bill_reference||'',x.remarks||'',x.spent_at]);await c.query("INSERT INTO transaction_log(transaction_date,transaction_type,amount,description,payment_mode,reference_id,remarks,source_id) VALUES($1,'Expense',$2,$3,$4,$5,$6,$7)",[x.spent_at,x.amount,x.description||x.expense_head,x.payment_mode||'',x.bill_reference||'',x.remarks||'',r.rows[0].id]);await c.query('COMMIT');res.json(r.rows[0])}catch(e){await c.query('ROLLBACK');res.status(500).json({error:e.message})}finally{c.release()}});
app.put('/api/expenses/:id',auth,admin,async(req,res)=>{const x=req.body,c=await db.connect();try{await c.query('BEGIN');const r=await c.query('UPDATE expenses SET expense_head=$1,description=$2,amount=$3,payment_mode=$4,paid_by=$5,bill_reference=$6,remarks=$7,spent_at=$8 WHERE id=$9 RETURNING *',[x.expense_head,x.description||'',x.amount,x.payment_mode||'',x.paid_by||'',x.bill_reference||'',x.remarks||'',x.spent_at,req.params.id]);if(!r.rows[0])throw Error('Expense not found');await c.query("UPDATE transaction_log SET transaction_date=$1,amount=$2,description=$3,payment_mode=$4,reference_id=$5,remarks=$6 WHERE transaction_type='Expense' AND source_id=$7",[x.spent_at,x.amount,x.description||x.expense_head,x.payment_mode||'',x.bill_reference||'',x.remarks||'',req.params.id]);await c.query('COMMIT');res.json(r.rows[0])}catch(e){await c.query('ROLLBACK');res.status(500).json({error:e.message})}finally{c.release()}});
app.delete('/api/expenses/:id',auth,admin,async(req,res)=>{const c=await db.connect();try{await c.query('BEGIN');await c.query("DELETE FROM transaction_log WHERE transaction_type='Expense' AND source_id=$1",[req.params.id]);await c.query('DELETE FROM expenses WHERE id=$1',[req.params.id]);await c.query('COMMIT');res.json({ok:true})}catch(e){await c.query('ROLLBACK');res.status(500).json({error:e.message})}finally{c.release()}});
app.post('/api/budgets',auth,admin,async(req,res)=>{const x=req.body;if(!x.budget_head||!x.allocated_amount)return res.status(400).json({error:'Budget head and amount are required'});res.json((await q('INSERT INTO budgets(budget_head,allocated_amount,remarks) VALUES($1,$2,$3) RETURNING *',[x.budget_head,x.allocated_amount,x.remarks||''])).rows[0])});
app.put('/api/budgets/:id',auth,admin,async(req,res)=>{const x=req.body;res.json((await q('UPDATE budgets SET budget_head=$1,allocated_amount=$2,remarks=$3 WHERE id=$4 RETURNING *',[x.budget_head,x.allocated_amount,x.remarks||'',req.params.id])).rows[0])});
app.delete('/api/budgets/:id',auth,admin,async(req,res)=>{await q('DELETE FROM budgets WHERE id=$1',[req.params.id]);res.json({ok:true})});
app.get('/api/transactions',auth,async(req,res)=>{const s=(req.query.search||'').trim(),type=req.query.type||'',from=req.query.from||'1900-01-01',to=req.query.to||'2999-12-31';let sql="SELECT * FROM transaction_log WHERE transaction_date BETWEEN $1 AND $2 AND (description ILIKE $3 OR COALESCE(remarks,'') ILIKE $3 OR transaction_type ILIKE $3)";const p=[from,to,'%'+s+'%'];if(type){sql+=' AND transaction_type=$4';p.push(type)}sql+=' ORDER BY transaction_date DESC,created_at DESC';res.json((await q(sql,p)).rows)});
app.get('/api/users',auth,admin,async(req,res)=>res.json((await q('SELECT id,name,email,role,active,created_at FROM users ORDER BY id')).rows));
app.post('/api/users',auth,admin,async(req,res)=>{const x=req.body;if(!x.name||!x.email||!x.password)return res.status(400).json({error:'Name, email and password required'});try{const h=await bcrypt.hash(x.password,12),r=await q('INSERT INTO users(name,email,password_hash,role) VALUES($1,$2,$3,$4) RETURNING id,name,email,role,active',[x.name,x.email.toLowerCase(),h,x.role==='admin'?'admin':'user']);res.json(r.rows[0])}catch(e){res.status(400).json({error:e.code==='23505'?'Email already exists':e.message})}});
app.patch('/api/users/:id',auth,admin,async(req,res)=>{const x=req.body;if(String(req.params.id)===String(req.user.id)&&x.active===false)return res.status(400).json({error:'You cannot disable yourself'});res.json((await q('UPDATE users SET name=COALESCE($1,name),role=COALESCE($2,role),active=COALESCE($3,active) WHERE id=$4 RETURNING id,name,email,role,active',[x.name||null,x.role||null,x.active===undefined?null:x.active,req.params.id])).rows[0])});
app.delete('/api/users/:id',auth,admin,async(req,res)=>{if(String(req.params.id)===String(req.user.id))return res.status(400).json({error:'You cannot delete yourself'});await q('DELETE FROM users WHERE id=$1',[req.params.id]);res.json({ok:true})});
app.get('/api/export/:type',auth,async(req,res)=>{const type=req.params.type;let rows=[];if(type==='donations')rows=(await q('SELECT donated_at AS date,donor_name AS donor,mobile,amount,payment_mode,donation_for,remarks FROM donations ORDER BY donated_at DESC,id DESC')).rows;else if(type==='expenses')rows=(await q('SELECT spent_at AS date,expense_head,description,amount,payment_mode,paid_by,bill_reference,remarks FROM expenses ORDER BY spent_at DESC,id DESC')).rows;else rows=(await q('SELECT transaction_date AS date,transaction_type,amount,description,payment_mode,reference_id,remarks FROM transaction_log ORDER BY transaction_date DESC,created_at DESC')).rows;const ws=xlsx.utils.json_to_sheet(rows),wb=xlsx.utils.book_new();xlsx.utils.book_append_sheet(wb,ws,'Data');const out=xlsx.write(wb,{type:'buffer',bookType:'xlsx'});res.setHeader('Content-Disposition',`attachment; filename=${type}-report.xlsx`);res.type('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet').send(out)});
app.post('/api/documents',auth,admin,upload.single('file'),async(req,res)=>{if(!req.file)return res.status(400).json({error:'File required'});const r=await q('INSERT INTO documents(title,filename,stored_name,uploaded_by) VALUES($1,$2,$3,$4) RETURNING *',[req.body.title||req.file.originalname,req.file.originalname,req.file.filename,req.user.id]);res.json(r.rows[0])});
app.get('/api/documents',auth,async(req,res)=>res.json((await q('SELECT d.id,d.title,d.filename,d.created_at,u.name uploaded_by FROM documents d LEFT JOIN users u ON u.id=d.uploaded_by ORDER BY d.created_at DESC')).rows));
app.get('/api/documents/:id/download',auth,async(req,res)=>{const r=(await q('SELECT * FROM documents WHERE id=$1',[req.params.id])).rows[0];if(!r)return res.sendStatus(404);res.download(path.join(UP,r.stored_name),r.filename)});
app.delete('/api/documents/:id',auth,admin,async(req,res)=>{const r=(await q('SELECT * FROM documents WHERE id=$1',[req.params.id])).rows[0];if(r){try{fs.unlinkSync(path.join(UP,r.stored_name))}catch{};await q('DELETE FROM documents WHERE id=$1',[req.params.id])}res.json({ok:true})});
app.get('*',(req,res)=>res.type('html').send(`<!doctype html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#c5161d"><link rel="manifest" href="/manifest.json"><title>দুর্গা পূজা সমিতি</title><style>
:root{--red:#c5161d;--red2:#8e0c12;--gold:#f6b73c;--bg:#fff7ef;--ink:#351313;--muted:#777;--green:#0c9b61;--blue:#1684e8;--purple:#7651e8;--shadow:0 8px 24px rgba(82,24,16,.10)}*{box-sizing:border-box}body{margin:0;background:#151515;font-family:system-ui,-apple-system,"Noto Sans Bengali",Arial,sans-serif;color:var(--ink)}button,input,select,textarea{font:inherit}.app{max-width:520px;margin:auto;min-height:100vh;background:var(--bg);overflow:hidden}.hidden{display:none!important}.top{background:linear-gradient(135deg,var(--red2),var(--red));color:#fff;padding:12px 14px;display:flex;align-items:center;gap:10px;position:sticky;top:0;z-index:20;box-shadow:0 4px 15px #0002}.top h1{font-size:19px;margin:0;flex:1}.iconbtn{border:0;background:#ffffff22;color:#fff;border-radius:12px;width:40px;height:40px;font-size:21px}.hero{height:265px;position:relative;background:#6e070b;overflow:hidden}.hero img{width:100%;height:100%;object-fit:cover;opacity:.92}.hero:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,#7e090ddd,transparent 60%)}.heroText{position:absolute;z-index:2;bottom:18px;left:18px;color:#fff}.heroText h1{font-size:28px;margin:0 0 5px;text-shadow:0 2px 8px #000}.heroText p{margin:0;font-size:14px}.stats{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:12px}.stat{border-radius:16px;padding:14px;color:#fff;box-shadow:var(--shadow);min-height:88px}.stat b{font-size:20px;display:block;margin-top:7px}.s1{background:#12a967}.s2{background:#1684e8}.s3{background:#ef4d3f}.s4{background:#f39b15}.s5{grid-column:1/3;background:linear-gradient(135deg,#6844e8,#914be7)}.section{padding:0 12px 12px}.panel{background:#fff;border-radius:18px;padding:14px;margin-bottom:12px;box-shadow:var(--shadow)}.panelTitle{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}.panelTitle h3{margin:0;font-size:17px}.actions{display:grid;grid-template-columns:1fr 1fr;gap:10px}.action{border:0;border-radius:15px;padding:14px;background:#fff;box-shadow:var(--shadow);text-align:left;font-weight:700}.action span{font-size:25px;display:block;margin-bottom:6px}.action small{font-weight:500;color:#777}.tx{display:flex;justify-content:space-between;gap:10px;padding:11px 0;border-bottom:1px solid #eee}.tx:last-child{border-bottom:0}.tx small{color:#777}.plus{color:var(--green);font-weight:800}.minus{color:#e03d37;font-weight:800}.bottom{position:sticky;bottom:0;background:#fff;border-top:1px solid #eee;display:grid;grid-template-columns:repeat(5,1fr);padding:7px 4px calc(7px + env(safe-area-inset-bottom));z-index:20}.nav{border:0;background:none;color:#777;font-size:11px}.nav b{display:block;font-size:20px}.nav.active{color:var(--red);font-weight:800}.screen{padding-bottom:72px}.form{padding:14px}.label{font-size:13px;font-weight:700;margin:10px 0 5px;display:block}.input,.select,.textarea{width:100%;border:1px solid #ddd;border-radius:12px;padding:12px;background:#fff;outline:none}.textarea{min-height:80px;resize:vertical}.btn{border:0;border-radius:12px;padding:13px 16px;font-weight:800;color:#fff;background:var(--red);width:100%;margin-top:12px}.btn.green{background:var(--green)}.btn.blue{background:var(--blue)}.btn.outline{background:#fff;color:var(--red);border:1px solid #e3b7b7}.rowBtns{display:flex;gap:8px}.rowBtns .btn{flex:1}.tableWrap{overflow:auto}.table{width:100%;border-collapse:collapse;font-size:12px}.table th,.table td{padding:9px 6px;border-bottom:1px solid #eee;text-align:left;white-space:nowrap}.table th{color:#777}.search{display:flex;gap:8px}.search .input{flex:1}.pill{display:inline-block;padding:5px 8px;border-radius:20px;background:#f3f3f3;font-size:11px}.login{min-height:100vh;background:#fff7ef}.loginHero{height:390px;background:#8b0b10;position:relative}.loginHero img{width:100%;height:100%;object-fit:cover}.loginHero:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,#8b0b10,transparent 70%)}.loginTitle{position:absolute;bottom:24px;left:22px;color:#fff;z-index:2}.loginTitle h1{font-size:29px;margin:0}.loginCard{margin:-10px 14px 20px;position:relative;z-index:3;background:#fff;border-radius:22px;padding:18px;box-shadow:var(--shadow)}.menuItem{display:flex;align-items:center;gap:12px;padding:13px 5px;border-bottom:1px solid #eee}.menuItem span{font-size:22px}.menuItem b{flex:1}.chart{display:flex;align-items:end;height:150px;gap:12px;padding:15px 5px 5px}.bar{flex:1;background:linear-gradient(#c5161d,#f0a21b);border-radius:8px 8px 0 0;min-height:8px}.barLabel{text-align:center;font-size:10px;color:#666}.modal{position:fixed;inset:0;background:#0008;z-index:50;display:flex;align-items:end}.modalBox{width:100%;max-width:520px;margin:auto;background:#fff;border-radius:24px 24px 0 0;max-height:90vh;overflow:auto}.modalHead{padding:15px;border-bottom:1px solid #eee;display:flex;align-items:center}.modalHead b{flex:1}.close{border:0;background:#eee;border-radius:50%;width:34px;height:34px}.toast{position:fixed;left:50%;bottom:90px;transform:translateX(-50%);background:#222;color:#fff;padding:10px 15px;border-radius:12px;z-index:100;display:none}.loading{padding:50px;text-align:center;color:#777}
@media(min-width:700px){.app{box-shadow:0 0 30px #0006}.modal{align-items:center}.modalBox{border-radius:24px;max-width:520px}}
</style></head><body><div id="root"></div><div id="toast" class="toast"></div><script>
const root=document.getElementById('root'),toastEl=document.getElementById('toast');const money=n=>'₹ '+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:0,maximumFractionDigits:2});const token=()=>localStorage.getItem('dp_token');let me=null;
async function api(url,opt={}){opt.headers={...(opt.headers||{})};if(!(opt.body instanceof FormData))opt.headers['Content-Type']='application/json';if(token())opt.headers.Authorization='Bearer '+token();let r=await fetch('/api'+url,opt),t=await r.text(),d=t?JSON.parse(t):{};if(!r.ok)throw Error(d.error||'Request failed');return d}
function toast(s){toastEl.textContent=s;toastEl.style.display='block';setTimeout(()=>toastEl.style.display='none',2200)}
function dateNow(){return new Date().toISOString().slice(0,10)}
async function boot(){try{me=await api('/me');dashboard()}catch(e){setupOrLogin()}}
async function setupOrLogin(){try{let h=await fetch('/api/health'); if(!h.ok)throw 0; let x=await fetch('/api/setup-admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({})});login(false)}catch(e){login(false)}}
function login(){root.innerHTML=\`<div class="login"><div class="loginHero"><img src="data:image/jpeg;base64,"><div class="loginTitle"><h1>দুর্গা পূজা সমিতি</h1><div>একতার বন্ধন, সবার জন্য</div></div></div><div class="loginCard"><h2 style="margin:0 0 4px">অ্যাডমিন / ইউজার লগইন</h2><p style="color:#777;margin-top:5px">আপনার অ্যাকাউন্ট দিয়ে প্রবেশ করুন</p><label class="label">ইমেইল / মোবাইল</label><input class="input" id="lem" type="email" placeholder="name@example.com"><label class="label">পাসওয়ার্ড</label><input class="input" id="lpw" type="password" placeholder="পাসওয়ার্ড লিখুন"><button class="btn" onclick="doLogin()">লগইন করুন</button><button class="btn outline" onclick="showSetup()">প্রথমবার? অ্যাডমিন অ্যাকাউন্ট তৈরি করুন</button></div></div>\`}
async function doLogin(){try{let x=await api('/login',{method:'POST',body:JSON.stringify({email:lem.value,password:lpw.value})});localStorage.dp_token=x.token;me=x.user;dashboard()}catch(e){toast(e.message)}}
function showSetup(){root.innerHTML=\`<div class="login"><div class="loginHero" style="height:300px"><img src="data:image/jpeg;base64,"><div class="loginTitle"><h1>প্রথম সেটআপ</h1><div>শুধু প্রথম অ্যাডমিন তৈরি করুন</div></div></div><div class="loginCard"><label class="label">অ্যাডমিনের নাম</label><input class="input" id="sn"><label class="label">ইমেইল</label><input class="input" id="se" type="email"><label class="label">পাসওয়ার্ড (কমপক্ষে ৬ অক্ষর)</label><input class="input" id="sp" type="password"><button class="btn green" onclick="setupAdmin()">অ্যাডমিন তৈরি করুন</button><button class="btn outline" onclick="login()">লগইনে ফিরে যান</button></div></div>\`}
async function setupAdmin(){try{let x=await api('/setup-admin',{method:'POST',body:JSON.stringify({name:sn.value,email:se.value,password:sp.value})});localStorage.dp_token=x.token;me=x.user;dashboard()}catch(e){toast(e.message)}}
function shell(title,content,active='home',back=false){root.innerHTML=\`<div class="app"><div class="top">\${back?\`<button class="iconbtn" onclick="dashboard()">‹</button>\`:''}<h1>\${title}</h1><button class="iconbtn" onclick="menu()">☰</button></div><main class="screen">\${content}</main><nav class="bottom"><button class="nav \${active==='home'?'active':''}" onclick="dashboard()"><b>⌂</b>হোম</button><button class="nav \${active==='donation'?'active':''}" onclick="donations()"><b>₹</b>অনুদান</button><button class="nav \${active==='expense'?'active':''}" onclick="expenses()"><b>▣</b>খরচ</button><button class="nav \${active==='report'?'active':''}" onclick="reports()"><b>◫</b>রিপোর্ট</button><button class="nav \${active==='menu'?'active':''}" onclick="menu()"><b>☰</b>মেনু</button></nav></div>\`}
async function dashboard(){let x;try{x=await api('/dashboard')}catch(e){localStorage.removeItem('dp_token');return login()}let admin=me?.role==='admin';let tx=x.transactions.map(t=>\`<div class="tx"><div><b>\${t.description||t.transaction_type}</b><br><small>\${t.transaction_date} · \${t.payment_mode||''}</small></div><div class="\${t.transaction_type==='Expense'?'minus':'plus'}">\${t.transaction_type==='Expense'?'−':'+'}\${money(t.amount)}</div></div>\`).join('')||'<p style="color:#777">এখনও কোনো লেনদেন নেই</p>';shell('অ্যাডমিন ড্যাশবোর্ড',\`<div class="hero"><img src="data:image/jpeg;base64,"><div class="heroText"><h1>শুভ দুর্গা পূজা</h1><p>দুর্গা পূজা সমিতি · একতার বন্ধন, সবার জন্য</p></div></div><div class="stats"><div class="stat s1">মোট অনুদান<b>\${money(x.donation)}</b></div><div class="stat s2">অনুদানকারী<b>\${'—'}</b></div><div class="stat s3">মোট খরচ<b>\${money(x.expense)}</b></div><div class="stat s4">মোট বাজেট<b>\${money(x.budget)}</b></div><div class="stat s5">বর্তমান হাতে থাকা তহবিল<b>\${money(x.fund)}</b></div></div><div class="section"><div class="panel"><div class="panelTitle"><h3>দ্রুত কাজ</h3><span class="pill">\${admin?'Admin':'View Only'}</span></div><div class="actions">\${admin?\`<button class="action" onclick="donationForm()"><span>💰</span>অনুদান এন্ট্রি<small>নতুন অনুদান যোগ করুন</small></button><button class="action" onclick="expenseForm()"><span>💸</span>খরচ এন্ট্রি<small>নতুন খরচ যোগ করুন</small></button><button class="action" onclick="budgetForm()"><span>🎯</span>বাজেট এন্ট্রি<small>বাজেট যোগ করুন</small></button>\`:''}<button class="action" onclick="reports()"><span>📊</span>রিপোর্ট<small>লেনদেন দেখুন</small></button></div></div><div class="panel"><div class="panelTitle"><h3>সর্বশেষ ১০টি লেনদেন</h3><button class="link" onclick="transactions()">সব দেখুন</button></div>\${tx}</div></div>\`,'home')}
function formModal(title,body){let m=document.createElement('div');m.className='modal';m.innerHTML=\`<div class="modalBox"><div class="modalHead"><b>\${title}</b><button class="close" onclick="this.closest('.modal').remove()">×</button></div>\${body}</div>\`;document.body.appendChild(m);return m}
function donationForm(id=null,data={}){let m=formModal(id?'অনুদান সম্পাদনা':'অনুদান এন্ট্রি',\`<div class="form"><label class="label">অনুদানকারীর নাম *</label><input class="input" id="dn" value="\${data.donor_name||''}"><label class="label">মোবাইল নম্বর</label><input class="input" id="dm" value="\${data.mobile||''}"><label class="label">অনুদানের পরিমাণ (₹) *</label><input class="input" id="da" type="number" value="\${data.amount||''}"><label class="label">পরিশোধের মাধ্যম</label><select class="select" id="dp"><option>\${data.payment_mode||'নগদ'}</option><option>UPI</option><option>Bank Transfer</option><option>Cheque</option><option>নগদ</option></select><label class="label">উদ্দেশ্য</label><input class="input" id="df" value="\${data.donation_for||''}"><label class="label">তারিখ *</label><input class="input" id="dd" type="date" value="\${data.donated_at||dateNow()}"><label class="label">বিবরণ / মন্তব্য</label><textarea class="textarea" id="dr">\${data.remarks||''}</textarea><button class="btn green" onclick="saveDonation(\${id||0})">সংরক্ষণ করুন</button></div>\`);}
async function saveDonation(id){let x={donor_name:dn.value,mobile:dm.value,amount:Number(da.value),payment_mode:dp.value,donation_for:df.value,donated_at:dd.value,remarks:dr.value};try{await api(id?'/donations/'+id:'/donations',{method:id?'PUT':'POST',body:JSON.stringify(x)});document.querySelector('.modal').remove();toast('অনুদান সংরক্ষিত');donations()}catch(e){toast(e.message)}}
async function donations(){let rows=await api('/donations');shell('অনুদানকারীর তালিকা',\`<div class="section"><div class="panel"><div class="search"><input class="input" id="dsearch" placeholder="নাম বা মোবাইল দিয়ে খুঁজুন"><button class="btn" style="width:auto;margin:0" onclick="filterDonations()">খুঁজুন</button></div>\${me.role==='admin'?'<button class="btn green" onclick="donationForm()">＋ নতুন অনুদান</button>':''}</div><div class="panel"><div class="tableWrap"><table class="table"><thead><tr><th>তারিখ</th><th>নাম</th><th>মোবাইল</th><th>টাকা</th>\${me.role==='admin'?'<th>Action</th>':''}</tr></thead><tbody id="drows">\${rows.map(d=>\`<tr><td>\${d.donated_at}</td><td>\${d.donor_name}</td><td>\${d.mobile||''}</td><td>\${money(d.amount)}</td>\${me.role==='admin'?\`<td><button onclick='donationForm(\${d.id},\${JSON.stringify(d)})'>✎</button> <button onclick='deleteDonation(\${d.id})'>🗑</button></td>\`:''}</tr>\`).join('')}</tbody></table></div></div></div>\`,'donation')}
async function filterDonations(){let r=await api('/donations?search='+encodeURIComponent(dsearch.value));document.getElementById('drows').innerHTML=r.map(d=>\`<tr><td>\${d.donated_at}</td><td>\${d.donor_name}</td><td>\${d.mobile||''}</td><td>\${money(d.amount)}</td>\${me.role==='admin'?\`<td><button onclick='donationForm(\${d.id},\${JSON.stringify(d)})'>✎</button> <button onclick='deleteDonation(\${d.id})'>🗑</button></td>\`:''}</tr>\`).join('')}
async function deleteDonation(id){if(confirm('এই অনুদান মুছে ফেলবেন?')){await api('/donations/'+id,{method:'DELETE'});donations()}}
function expenseForm(id=null,data={}){formModal(id?'খরচ সম্পাদনা':'খরচ এন্ট্রি',\`<div class="form"><label class="label">খরচের শিরোনাম *</label><input class="input" id="eh" value="\${data.expense_head||''}"><label class="label">খরচের বিবরণ</label><input class="input" id="ed" value="\${data.description||''}"><label class="label">পরিমাণ (₹) *</label><input class="input" id="ea" type="number" value="\${data.amount||''}"><label class="label">পরিশোধের মাধ্যম</label><select class="select" id="ep"><option>\${data.payment_mode||'নগদ'}</option><option>UPI</option><option>Bank Transfer</option><option>Cheque</option><option>নগদ</option></select><label class="label">বিল / রেফারেন্স</label><input class="input" id="eb" value="\${data.bill_reference||''}"><label class="label">তারিখ *</label><input class="input" id="ee" type="date" value="\${data.spent_at||dateNow()}"><label class="label">মন্তব্য</label><textarea class="textarea" id="er">\${data.remarks||''}</textarea><button class="btn blue" onclick="saveExpense(\${id||0})">সংরক্ষণ করুন</button></div>\`)}
async function saveExpense(id){let x={expense_head:eh.value,description:ed.value,amount:Number(ea.value),payment_mode:ep.value,bill_reference:eb.value,spent_at:ee.value,remarks:er.value};try{await api(id?'/expenses/'+id:'/expenses',{method:id?'PUT':'POST',body:JSON.stringify(x)});document.querySelector('.modal').remove();toast('খরচ সংরক্ষিত');expenses()}catch(e){toast(e.message)}}
async function expenses(){let rows=await api('/expenses');shell('খরচের তালিকা',\`<div class="section"><div class="panel"><div class="search"><input class="input" id="esearch" placeholder="খরচের বিবরণ দিয়ে খুঁজুন"><button class="btn" style="width:auto;margin:0" onclick="filterExpenses()">খুঁজুন</button></div>\${me.role==='admin'?'<button class="btn blue" onclick="expenseForm()">＋ নতুন খরচ</button>':''}</div><div class="panel"><div class="tableWrap"><table class="table"><thead><tr><th>তারিখ</th><th>বিবরণ</th><th>পরিমাণ</th>\${me.role==='admin'?'<th>Action</th>':''}</tr></thead><tbody id="erows">\${rows.map(e=>\`<tr><td>\${e.spent_at}</td><td>\${e.expense_head}<br><small>\${e.description||''}</small></td><td>\${money(e.amount)}</td>\${me.role==='admin'?\`<td><button onclick='expenseForm(\${e.id},\${JSON.stringify(e)})'>✎</button> <button onclick='deleteExpense(\${e.id})'>🗑</button></td>\`:''}</tr>\`).join('')}</tbody></table></div></div></div>\`,'expense')}
async function filterExpenses(){let r=await api('/expenses?search='+encodeURIComponent(esearch.value));document.getElementById('erows').innerHTML=r.map(e=>\`<tr><td>\${e.spent_at}</td><td>\${e.expense_head}<br><small>\${e.description||''}</small></td><td>\${money(e.amount)}</td>\${me.role==='admin'?\`<td><button onclick='expenseForm(\${e.id},\${JSON.stringify(e)})'>✎</button> <button onclick='deleteExpense(\${e.id})'>🗑</button></td>\`:''}</tr>\`).join('')}
async function deleteExpense(id){if(confirm('এই খরচ মুছে ফেলবেন?')){await api('/expenses/'+id,{method:'DELETE'});expenses()}}
function budgetForm(id=null,data={}){formModal(id?'বাজেট সম্পাদনা':'বাজেট এন্ট্রি',\`<div class="form"><label class="label">বাজেট বিভাগ *</label><input class="input" id="bh" value="\${data.budget_head||''}"><label class="label">বাজেট (₹) *</label><input class="input" id="ba" type="number" value="\${data.allocated_amount||''}"><label class="label">মন্তব্য</label><textarea class="textarea" id="br">\${data.remarks||''}</textarea><button class="btn" onclick="saveBudget(\${id||0})">সংরক্ষণ করুন</button></div>\`)}
async function saveBudget(id){try{await api(id?'/budgets/'+id:'/budgets',{method:id?'PUT':'POST',body:JSON.stringify({budget_head:bh.value,allocated_amount:Number(ba.value),remarks:br.value})});document.querySelector('.modal').remove();budgets()}catch(e){toast(e.message)}}
async function budgets(){let r=await api('/budgets');shell('বাজেট ব্যবস্থাপনা',\`<div class="section"><div class="panel"><h3>মোট বাজেট</h3><div style="font-size:28px;font-weight:800">\${money(r.reduce((a,x)=>a+Number(x.allocated_amount),0))}</div>\${me.role==='admin'?'<button class="btn" onclick="budgetForm()">＋ নতুন বাজেট</button>':''}</div><div class="panel"><div class="tableWrap"><table class="table"><thead><tr><th>বিভাগ</th><th>বাজেট</th>\${me.role==='admin'?'<th>Action</th>':''}</tr></thead><tbody>\${r.map(b=>\`<tr><td>\${b.budget_head}</td><td>\${money(b.allocated_amount)}</td>\${me.role==='admin'?\`<td><button onclick='budgetForm(\${b.id},\${JSON.stringify(b)})'>✎</button> <button onclick='deleteBudget(\${b.id})'>🗑</button></td>\`:''}</tr>\`).join('')}</tbody></table></div></div></div>\`,'menu')}
async function deleteBudget(id){if(confirm('এই বাজেট মুছে ফেলবেন?')){await api('/budgets/'+id,{method:'DELETE'});budgets()}}
async function transactions(){let r=await api('/transactions');shell('লেনদেন অনুসন্ধান',\`<div class="section"><div class="panel"><div class="search"><input class="input" id="tsearch" placeholder="নাম / বিবরণ / রেফারেন্স"><button class="btn" style="width:auto;margin:0" onclick="filterTx()">খুঁজুন</button></div><div style="display:flex;gap:8px;margin-top:8px"><select class="select" id="ttype"><option value="">সব ধরন</option><option>Donation</option><option>Expense</option></select><button class="btn green" style="margin:0" onclick="exportX('transactions')">Excel</button></div></div><div class="panel"><div class="tableWrap"><table class="table"><thead><tr><th>তারিখ</th><th>ধরন</th><th>বিবরণ</th><th>টাকা</th></tr></thead><tbody id="trows">\${txRows(r)}</tbody></table></div></div></div>\`,'report')}
function txRows(r){return r.map(t=>\`<tr><td>\${t.transaction_date}</td><td><span class="pill">\${t.transaction_type}</span></td><td>\${t.description||''}</td><td>\${money(t.amount)}</td></tr>\`).join('')}
async function filterTx(){let u='/transactions?search='+encodeURIComponent(tsearch.value)+'&type='+encodeURIComponent(ttype.value);document.getElementById('trows').innerHTML=txRows(await api(u))}
async function reports(){let x=await api('/dashboard');shell('রিপোর্ট ও সারাংশ',\`<div class="section"><div class="panel"><div class="panelTitle"><h3>আর্থিক সারাংশ</h3></div><div class="tx"><span>মোট অনুদান</span><b class="plus">\${money(x.donation)}</b></div><div class="tx"><span>মোট খরচ</span><b class="minus">\${money(x.expense)}</b></div><div class="tx"><span>মোট বাজেট</span><b>\${money(x.budget)}</b></div><div class="tx"><span>বাকি তহবিল</span><b style="color:var(--purple)">\${money(x.fund)}</b></div></div><div class="panel"><h3>রিপোর্ট এক্সপোর্ট</h3><button class="btn green" onclick="exportX('transactions')">Excel — সকল লেনদেন</button><button class="btn blue" onclick="exportX('donations')">Excel — অনুদান</button><button class="btn" onclick="exportX('expenses')">Excel — খরচ</button><button class="btn outline" onclick="window.print()">🖨 Print / PDF</button></div></div>\`,'report')}
function exportX(type){window.location='/api/export/'+type}
async function menu(){shell('মেনু',\`<div class="section"><div class="panel"><div class="menuItem" onclick="dashboard()"><span>🏠</span><b>ড্যাশবোর্ড</b>›</div><div class="menuItem" onclick="donations()"><span>💰</span><b>অনুদান এন্ট্রি ও তালিকা</b>›</div><div class="menuItem" onclick="expenses()"><span>💸</span><b>খরচ এন্ট্রি ও তালিকা</b>›</div><div class="menuItem" onclick="budgets()"><span>🎯</span><b>বাজেট ব্যবস্থাপনা</b>›</div><div class="menuItem" onclick="transactions()"><span>🔎</span><b>লেনদেন অনুসন্ধান</b>›</div><div class="menuItem" onclick="reports()"><span>📊</span><b>রিপোর্ট ও এক্সেল</b>›</div><div class="menuItem" onclick="documents()"><span>📄</span><b>ডকুমেন্ট</b>›</div>\${me.role==='admin'?'<div class="menuItem" onclick="users()"><span>👥</span><b>ব্যবহারকারী ব্যবস্থাপনা</b>›</div>':''}<div class="menuItem" onclick="profile()"><span>⚙️</span><b>প্রোফাইল / সেটিংস</b>›</div><div class="menuItem" onclick="logout()" style="color:#d11"><span>🚪</span><b>লগআউট</b>›</div></div></div>\`,'menu')}
async function users(){let r=await api('/users');shell('ব্যবহারকারী ব্যবস্থাপনা',\`<div class="section"><div class="panel"><button class="btn blue" onclick="userForm()">＋ নতুন ব্যবহারকারী</button></div><div class="panel"><div class="tableWrap"><table class="table"><thead><tr><th>নাম</th><th>ইমেইল</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody>\${r.map(u=>\`<tr><td>\${u.name}</td><td>\${u.email}</td><td>\${u.role}</td><td>\${u.active?'Active':'Disabled'}</td><td><button onclick='toggleUser(\${u.id},\${!u.active})'>\${u.active?'Disable':'Enable'}</button></td></tr>\`).join('')}</tbody></table></div></div></div>\`,'menu')}
function userForm(){formModal('নতুন ব্যবহারকারী',\`<div class="form"><label class="label">নাম</label><input class="input" id="un"><label class="label">ইমেইল</label><input class="input" id="ue"><label class="label">পাসওয়ার্ড</label><input class="input" id="up" type="password"><label class="label">Role</label><select class="select" id="ur"><option value="user">User — View Only</option><option value="admin">Admin</option></select><button class="btn blue" onclick="saveUser()">ব্যবহারকারী তৈরি করুন</button></div>\`)}
async function saveUser(){try{await api('/users',{method:'POST',body:JSON.stringify({name:un.value,email:ue.value,password:up.value,role:ur.value})});document.querySelector('.modal').remove();users();toast('ব্যবহারকারী তৈরি হয়েছে')}catch(e){toast(e.message)}}
async function toggleUser(id,active){await api('/users/'+id,{method:'PATCH',body:JSON.stringify({active})});users()}
async function documents(){let r=await api('/documents');shell('ডকুমেন্ট',\`<div class="section"><div class="panel">\${me.role==='admin'?'<label class="label">ডকুমেন্টের নাম</label><input class="input" id="docTitle" placeholder="যেমন: মণ্ডপ বিল"><label class="label">ফাইল</label><input class="input" id="docFile" type="file"><button class="btn blue" onclick="uploadDoc()">ফাইল আপলোড করুন</button>':'<p style="color:#777">শুধু Admin ফাইল আপলোড/ডিলিট করতে পারবেন।</p>'}</div><div class="panel">\${r.map(d=>\`<div class="tx"><div><b>\${d.title}</b><br><small>\${d.filename} · \${new Date(d.created_at).toLocaleDateString('en-IN')}</small></div><div><button onclick="window.location='/api/documents/\${d.id}/download'">⬇</button>\${me.role==='admin'?\`<button onclick="deleteDoc(\${d.id})">🗑</button>\`:''}</div></div>\`).join('')||'<p>কোনো ডকুমেন্ট নেই</p>'}</div></div>\`,'menu')}
async function uploadDoc(){let f=docFile.files[0];if(!f)return toast('ফাইল নির্বাচন করুন');let fd=new FormData();fd.append('file',f);fd.append('title',docTitle.value||f.name);try{await api('/documents',{method:'POST',body:fd});documents();toast('ফাইল আপলোড হয়েছে')}catch(e){toast(e.message)}}
async function deleteDoc(id){if(confirm('ডকুমেন্ট মুছে ফেলবেন?')){await api('/documents/'+id,{method:'DELETE'});documents()}}
function profile(){shell('প্রোফাইল / সেটিংস',\`<div class="section"><div class="panel"><div style="font-size:46px">👤</div><h2>\${me.name}</h2><p>\${me.email}</p><span class="pill">\${me.role==='admin'?'Admin':'View Only User'}</span></div><div class="panel"><div class="menuItem"><span>🔐</span><b>নিরাপদ লগইন</b><span>✓</span></div><div class="menuItem"><span>📱</span><b>Mobile PWA</b><span>✓</span></div><button class="btn" onclick="logout()">লগআউট</button></div></div>\`,'menu')}
function logout(){localStorage.removeItem('dp_token');me=null;login()}
boot();
</script></body></html>
`));
(async()=>{try{await q(fs.readFileSync(path.join(__dirname,'schema.sql'),'utf8'));app.listen(PORT,()=>console.log('Durga Puja Samiti running on '+PORT))}catch(e){console.error(e);process.exit(1)}})();
